var EP = {"pixel": {"guide": "Pixel", "world": {"en": "AI & Data", "fr": "IA et données", "nl": "AI en data"}, "title": {"en": "How does a computer learn to tell a cat from a dog?", "fr": "Comment un ordinateur apprend-il à reconnaître un chat d’un chien ?", "nl": "Hoe leert een computer een kat van een hond te onderscheiden?"}, "adult": {"en": "For grown-ups: the AI & Data world in the IMAGINE Scientific Universe", "fr": "Pour les adultes : le monde IA et données dans l’IMAGINE Scientific Universe", "nl": "Voor volwassenen: de wereld AI en data in het IMAGINE Scientific Universe"}, "scenes": [{"speaker": "Whyzz", "img": "Whyzz holds a tablet showing a fluffy animal photo; Pixel, a friendly kid guide in a blue suit with a pixel-grid badge, leans in curious; bright playful room", "en": "Pixel, look at this photo. Is it a cat or a dog? I know right away. But how would a computer know?", "fr": "Pixel, regarde cette photo. C’est un chat ou un chien ? Moi, je le vois tout de suite. Mais comment un ordinateur le saurait-il ?", "nl": "Pixel, kijk naar deze foto. Is het een kat of een hond? Ik zie het meteen. Maar hoe weet een computer dat?"}, {"speaker": "Pixel", "img": "close-up of a cat photo dissolving into a giant grid of tiny colored squares, Pixel pointing at the squares, glowing blue light", "en": "A computer doesn’t see a cat. It sees thousands of tiny colored dots, called pixels. That’s where my name comes from!", "fr": "Un ordinateur ne voit pas un chat. Il voit des milliers de petits points de couleur, qu’on appelle des pixels. C’est de là que vient mon nom !", "nl": "Een computer ziet geen kat. Hij ziet duizenden kleine gekleurde puntjes, die heten pixels. Daar komt mijn naam vandaan!"}, {"speaker": "Pixel", "img": "Pixel showing a giant stack of flashcards with cat and dog photos, each with a label CAT or DOG, a small cute robot computer studying them", "en": "So we teach it with examples. We show it thousands of photos, and each one has a label: cat, or dog. Like flashcards!", "fr": "Alors on lui apprend avec des exemples. On lui montre des milliers de photos, et chacune a une étiquette : chat ou chien. Comme des cartes pour réviser !", "nl": "Dus leren we hem met voorbeelden. We laten duizenden foto’s zien, en elke foto heeft een label: kat of hond. Net als flitskaarten!"}, {"speaker": "Pixel", "img": "the small robot computer guessing with a speech bubble question mark, green check and red cross symbols, arrows showing a loop: guess, check, adjust", "en": "The computer guesses, then checks the label. Wrong? It changes itself a tiny bit. It does this again and again. That is called training.", "fr": "L’ordinateur devine, puis il regarde l’étiquette. C’est faux ? Il se corrige un tout petit peu. Il recommence encore et encore. C’est ce qu’on appelle l’entraînement.", "nl": "De computer raadt, en kijkt dan naar het label. Fout? Dan past hij zichzelf een klein beetje aan. Dat doet hij steeds opnieuw. Dat heet trainen."}, {"speaker": "Whyzz", "img": "Whyzz and Pixel looking at a screen where the robot computer labels a new photo of a white cat as DOG, Whyzz laughing, Pixel thinking", "en": "But Pixel, it called this white cat a dog! Why?", "fr": "Mais Pixel, il a dit que ce chat blanc était un chien ! Pourquoi ?", "nl": "Maar Pixel, hij zegt dat deze witte kat een hond is! Waarom?"}, {"speaker": "Pixel", "img": "Pixel adding many different cat and dog photos of all colors and sizes to the stack, the robot computer now smiling with a green check, warm sunset light", "en": "Because we only showed it black cats! Good examples of every kind make a smarter computer. Computers learn from data. You learn from everything you explore!", "fr": "Parce qu’on ne lui a montré que des chats noirs ! De bons exemples de toutes sortes rendent l’ordinateur plus malin. Les ordinateurs apprennent avec des données. Toi, tu apprends avec tout ce que tu explores !", "nl": "Omdat we hem alleen zwarte katten lieten zien! Goede voorbeelden van allerlei soorten maken een slimmere computer. Computers leren van data. Jij leert van alles wat je ontdekt!"}], "quiz": [{"q": {"en": "What does a computer see in a photo?", "fr": "Que voit un ordinateur dans une photo ?", "nl": "Wat ziet een computer in een foto?"}, "o": {"en": ["A real cat", "Tiny colored dots called pixels", "Words"], "fr": ["Un vrai chat", "De petits points de couleur, les pixels", "Des mots"], "nl": ["Een echte kat", "Kleine gekleurde puntjes: pixels", "Woorden"]}, "ok": 1}, {"q": {"en": "How does the computer learn?", "fr": "Comment l’ordinateur apprend-il ?", "nl": "Hoe leert de computer?"}, "o": {"en": ["From many examples with labels", "By sleeping", "It already knows everything"], "fr": ["Avec beaucoup d’exemples étiquetés", "En dormant", "Il sait déjà tout"], "nl": ["Van veel voorbeelden met labels", "Door te slapen", "Hij weet alles al"]}, "ok": 0}, {"q": {"en": "What is training?", "fr": "Qu’est-ce que l’entraînement ?", "nl": "Wat is trainen?"}, "o": {"en": ["Running very fast", "Guess, check, change a little, repeat", "Taking one photo"], "fr": ["Courir très vite", "Deviner, vérifier, se corriger un peu, recommencer", "Prendre une seule photo"], "nl": ["Heel hard rennen", "Raden, controleren, een beetje aanpassen, herhalen", "Eén foto maken"]}, "ok": 1}, {"q": {"en": "Why did the computer call the white cat a dog?", "fr": "Pourquoi l’ordinateur a-t-il pris le chat blanc pour un chien ?", "nl": "Waarom dacht de computer dat de witte kat een hond was?"}, "o": {"en": ["It only saw black cats before", "White cats are dogs", "The photo was too big"], "fr": ["Il n’avait vu que des chats noirs", "Les chats blancs sont des chiens", "La photo était trop grande"], "nl": ["Hij had alleen zwarte katten gezien", "Witte katten zijn honden", "De foto was te groot"]}, "ok": 0}, {"q": {"en": "What makes a computer smarter?", "fr": "Qu’est-ce qui rend un ordinateur plus malin ?", "nl": "Wat maakt een computer slimmer?"}, "o": {"en": ["Fewer photos", "A louder sound", "Good examples of every kind"], "fr": ["Moins de photos", "Un son plus fort", "De bons exemples de toutes sortes"], "nl": ["Minder foto’s", "Een harder geluid", "Goede voorbeelden van allerlei soorten"]}, "ok": 2}]}, "qubi": {"guide": "Qubi", "world": {"en": "Quantum", "fr": "Quantique", "nl": "Quantum"}, "title": {"en": "Can a coin be heads and tails at the same time?", "fr": "Une pièce peut-elle être pile et face en même temps ?", "nl": "Kan een munt tegelijk kop en munt zijn?"}, "adult": {"en": "For grown-ups: article “Running Out of Cold” and Episode 001 “When GPUs Meet Quantum Computing”", "fr": "Pour les adultes : l’article « Running Out of Cold » et l’épisode 001 « When GPUs Meet Quantum Computing »", "nl": "Voor volwassenen: het artikel “Running Out of Cold” en aflevering 001 “When GPUs Meet Quantum Computing”"}, "scenes": [{"speaker": "Qubi", "img": "Qubi, a friendly kid guide in a purple suit with an atom badge, spinning a big shiny coin on a table, Whyzz watching wide-eyed, soft violet glow", "en": "Watch this coin spin, Whyzz. While it’s spinning, is it heads or tails?", "fr": "Regarde cette pièce tourner, Whyzz. Pendant qu’elle tourne, c’est pile ou face ?", "nl": "Kijk hoe deze munt draait, Whyzz. Is het kop of munt terwijl hij draait?"}, {"speaker": "Whyzz", "img": "close-up of the spinning coin blurred into a glowing sphere, Whyzz scratching head under a red cap, question marks floating", "en": "Hmm, a bit of both? I can’t tell until it stops!", "fr": "Hum, un peu des deux ? Je ne peux pas savoir tant qu’elle ne s’arrête pas !", "nl": "Hmm, een beetje van allebei? Ik weet het pas als hij stilligt!"}, {"speaker": "Qubi", "img": "a row of light switches and glowing 0 and 1 signs on a wall, Qubi flipping a switch, simple clean classroom style", "en": "Normal computers use bits. A bit is 0 or 1, like a light switch: off or on. Like a coin lying flat: heads or tails.", "fr": "Les ordinateurs normaux utilisent des bits. Un bit vaut 0 ou 1, comme un interrupteur : éteint ou allumé. Comme une pièce posée à plat : pile ou face.", "nl": "Gewone computers gebruiken bits. Een bit is 0 of 1, zoals een lichtschakelaar: uit of aan. Zoals een munt die plat ligt: kop of munt."}, {"speaker": "Qubi", "img": "a glowing qubit sphere floating, half blue 0 and half orange 1 swirling together, Qubi presenting it with open hands, starry violet background", "en": "Quantum computers use qubits. Before we look, a qubit can be a mix of 0 and 1 at once. Scientists call this superposition. The spinning coin is a picture to help us imagine it.", "fr": "Les ordinateurs quantiques utilisent des qubits. Avant qu’on regarde, un qubit peut être un mélange de 0 et de 1 en même temps. Les scientifiques appellent ça la superposition. La pièce qui tourne est une image pour nous aider à l’imaginer.", "nl": "Quantumcomputers gebruiken qubits. Voordat we kijken, kan een qubit een mengsel van 0 en 1 tegelijk zijn. Wetenschappers noemen dat superpositie. De draaiende munt is een plaatje om het ons voor te stellen."}, {"speaker": "Qubi", "img": "the coin landing flat showing heads with a small flash, next to it the qubit sphere turning into a single bright 1, Qubi with a magnifying glass", "en": "When we measure a qubit, it chooses: 0 or 1. Just like the coin when it lands. And qubits need to be colder than outer space to stay calm!", "fr": "Quand on mesure un qubit, il choisit : 0 ou 1. Comme la pièce quand elle retombe. Et les qubits doivent être plus froids que l’espace pour rester calmes !", "nl": "Als we een qubit meten, kiest hij: 0 of 1. Net als de munt als hij neerkomt. En qubits moeten kouder zijn dan de ruimte om rustig te blijven!"}, {"speaker": "Qubi", "img": "a shiny golden quantum computer chandelier in a frosty lab, Qubi and Whyzz in warm jackets smiling, snowflake sparkles", "en": "Quantum computers won’t replace your laptop. They are special helpers for very hard puzzles, like designing new medicines. What puzzle would you give one?", "fr": "Les ordinateurs quantiques ne remplaceront pas ton ordinateur portable. Ce sont des aides spéciales pour des énigmes très difficiles, comme inventer de nouveaux médicaments. Quelle énigme lui donnerais-tu ?", "nl": "Quantumcomputers vervangen je laptop niet. Het zijn speciale helpers voor heel moeilijke puzzels, zoals nieuwe medicijnen ontwerpen. Welke puzzel zou jij er een geven?"}], "quiz": [{"q": {"en": "What can a normal bit be?", "fr": "Que peut valoir un bit normal ?", "nl": "Wat kan een gewone bit zijn?"}, "o": {"en": ["0 or 1", "Any color", "A coin"], "fr": ["0 ou 1", "N’importe quelle couleur", "Une pièce"], "nl": ["0 of 1", "Elke kleur", "Een munt"]}, "ok": 0}, {"q": {"en": "What is a qubit before we look at it?", "fr": "Qu’est-ce qu’un qubit avant qu’on le regarde ?", "nl": "Wat is een qubit voordat we kijken?"}, "o": {"en": ["Always 0", "A mix of 0 and 1", "Broken"], "fr": ["Toujours 0", "Un mélange de 0 et de 1", "Cassé"], "nl": ["Altijd 0", "Een mengsel van 0 en 1", "Kapot"]}, "ok": 1}, {"q": {"en": "What happens when we measure a qubit?", "fr": "Que se passe-t-il quand on mesure un qubit ?", "nl": "Wat gebeurt er als we een qubit meten?"}, "o": {"en": ["It disappears", "It becomes 2", "It chooses 0 or 1"], "fr": ["Il disparaît", "Il devient 2", "Il choisit 0 ou 1"], "nl": ["Hij verdwijnt", "Hij wordt 2", "Hij kiest 0 of 1"]}, "ok": 2}, {"q": {"en": "Why are qubits kept so cold?", "fr": "Pourquoi garde-t-on les qubits si froids ?", "nl": "Waarom houden we qubits zo koud?"}, "o": {"en": ["To keep them calm", "To make ice cream", "Because they like snow"], "fr": ["Pour qu’ils restent calmes", "Pour faire de la glace", "Parce qu’ils aiment la neige"], "nl": ["Zodat ze rustig blijven", "Om ijs te maken", "Omdat ze van sneeuw houden"]}, "ok": 0}, {"q": {"en": "Will a quantum computer replace your laptop?", "fr": "Un ordinateur quantique va-t-il remplacer ton portable ?", "nl": "Vervangt een quantumcomputer je laptop?"}, "o": {"en": ["Yes, next year", "No, it is a helper for very hard puzzles", "Only on Sundays"], "fr": ["Oui, l’année prochaine", "Non, c’est une aide pour les énigmes très difficiles", "Seulement le dimanche"], "nl": ["Ja, volgend jaar", "Nee, het is een helper voor heel moeilijke puzzels", "Alleen op zondag"]}, "ok": 1}]}};
